# EA_LISTGAPS_V1 patch
import os, base64, json
B = os.environ.get('EA_PATCH_BASE') or '/opt/merchantiq'
f = os.path.join(B, 'ea_listing_gaps.py')
assert not os.path.exists(f) or 'EA_LISTGAPS_V1' in open(f).read(), 'another ea_listing_gaps.py exists'
s = base64.b64decode('').decode()
compile(s, f, 'exec')
open(f, 'w').write(s)
print('written ea_listing_gaps.py')
f3 = os.path.join(B, 'ea_mcp_jobs.json')
if os.path.exists(f3):
    J = json.load(open(f3))
    J.setdefault('jobs', {})['listing_gaps'] = {
        "seller": "all", "script": "ea_listing_gaps.py", "lane": "read",
        "args": ["^[A-Za-z0-9 ._&()-]{1,60}$", "^[^\\x00-\\x1f]{1,6000}$", "^(all)?$"],
        "timeout": 1800,
        "desc": "EA_LISTGAPS_V1 read-only: <seller> <SKU,SKU> [all] - per listing the sales-important attributes its product type allows but are empty (material, colour, size, special feature, hair type...), bullets under 5, short description, under 6 images"}
    json.dump(J, open(f3, 'w'), indent=1)
    print('registry: listing_gaps added')
print('PATCH_OK EA_LISTGAPS_V1')
